var data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch(e) {
        node.error('Invalid JSON', msg);
        return null;
    }
}

msg.headers = {
    'Content-Type': 'application/json'
};

msg.payload = {
    device_id: data.device_id || 'nodered-gateway-01',
    temperature: parseFloat(data.temperature || data.temp || 25.0),
    humidity: parseFloat(data.humidity || data.hum || 50.0),
    ph: parseFloat(data.ph || 6.5),
    rainfall: parseFloat(data.rainfall || data.rain || 0.0),
    tds: parseFloat(data.tds || 150.0),
    N: parseFloat(data.N || data.n || 80.0),
    P: parseFloat(data.P || data.p || 40.0),
    K: parseFloat(data.K || data.k || 40.0)
};

return msg;
